method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    ensures result == (CountOpen(brackets) == CountClose(brackets) && NoExcessClose(brackets))

    // CountOpen counts the number of opening brackets in the string.
    function CountOpen(s: string): int
        reads s
        ensures 0 <= CountOpen(s) <= |s|
    {
        var count := 0;
        var i := 0;
        while i < |s|
            invariant 0 <= i <= |s|
            invariant count == CountOpen(s[0..i])
        {
            if s[i] == '(' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

    // CountClose counts the number of closing brackets in the string.
    function CountClose(s: string): int
        reads s
        ensures 0 <= CountClose(s) <= |s|
    {
        var count := 0;
        var i := 0;
        while i < |s|
            invariant 0 <= i <= |s|
            invariant count == CountClose(s[0..i])
        {
            if s[i] == ')' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

    // NoExcessClose checks if there are no excess closing brackets.
    function NoExcessClose(s: string): bool
        reads s
    {
        var balance := 0;
        var i := 0;
        while i < |s|
            invariant 0 <= i <= |s|
            invariant balance >= 0
        {
            if s[i] == '(' {
                balance := balance + 1;
            } else if s[i] == ')' {
                balance := balance - 1;
            }
            i := i + 1;
        }
        return balance == 0;
    }
